/// Provisional grouping of incident evidence for the Organize stage (Sprint 5B).
///
/// Generated by [CollectionEngine] heuristics; refined by the investigator.
/// Distinct from [RelationshipGroup] (Investigation Connections).
class EvidenceCollection {
  EvidenceCollection({
    required this.id,
    required this.incidentId,
    required this.name,
    required this.systemGenerated,
    required this.displayOrder,
    required this.createdAt,
    required this.updatedAt,
    this.pending = false,
    this.category,
    List<String>? memberEvidenceIds,
  }) : memberEvidenceIds = List<String>.unmodifiable(
         memberEvidenceIds ?? const [],
       );

  final String id;
  final String incidentId;
  final String name;

  /// Organize interpretive type (`personParticipant`, `location`, …).
  /// Null for heuristic / Create Group collections.
  final String? category;

  /// True when created by heuristics (or future AI) rather than manual seed.
  final bool systemGenerated;

  /// True while an engine suggestion awaits accept / dismiss.
  ///
  /// `systemGenerated && pending` = reviewable suggestion.
  /// `!systemGenerated && !pending` = user-created or accepted collection.
  final bool pending;

  final int displayOrder;
  final DateTime createdAt;
  final DateTime updatedAt;

  /// Evidence ids assigned to this collection (canonical membership).
  final List<String> memberEvidenceIds;

  int get count => memberEvidenceIds.length;

  bool get isEmpty => memberEvidenceIds.isEmpty;

  bool get isPendingSuggestion => systemGenerated && pending;

  bool get isConfirmed => !pending && !systemGenerated;

  EvidenceCollection copyWith({
    String? name,
    bool? systemGenerated,
    bool? pending,
    int? displayOrder,
    DateTime? updatedAt,
    String? category,
    List<String>? memberEvidenceIds,
  }) {
    return EvidenceCollection(
      id: id,
      incidentId: incidentId,
      name: name ?? this.name,
      systemGenerated: systemGenerated ?? this.systemGenerated,
      pending: pending ?? this.pending,
      displayOrder: displayOrder ?? this.displayOrder,
      createdAt: createdAt,
      updatedAt: updatedAt ?? this.updatedAt,
      category: category ?? this.category,
      memberEvidenceIds: memberEvidenceIds ?? this.memberEvidenceIds,
    );
  }
}
